/**
 * Headless test double for the Google `maps3d` library.
 *
 * The Cloud/CI browsers have no GPU, so the real Map3DElement never produces a
 * canvas. This mock reproduces the *contract* the scene relies on — camera
 * properties, flyCameraTo / flyCameraAround / stopCameraAnimation, the
 * gmp-steadychange / gmp-animationend / gmp-headingchange events, and the
 * drawable element classes — so Playwright can exercise Watch/Atlas logic.
 * Loaded only when the page URL has `?mmd3d=mock`.
 */

import type { Maps3dLib } from "./google-scene3d";
import { metersPerPixel, zoomFromRange } from "./camera-math";

type LatLngAlt = { lat: number; lng: number; altitude?: number };

function define(tag: string, ctor: CustomElementConstructor): void {
  if (!customElements.get(tag)) customElements.define(tag, ctor);
}

/**
 * How long the mock takes to report `gmp-steadychange` after a camera write.
 * `?mmd3dsteady=<ms>` slows it down so tests can watch the first-paint hold
 * (`engine.hold(whenSteady)`) freeze the clock and then release.
 */
function steadyDelayMs(): number {
  try {
    const raw = new URLSearchParams(window.location.search).get("mmd3dsteady");
    const n = raw == null ? NaN : Number(raw);
    return Number.isFinite(n) && n >= 0 ? n : 120;
  } catch {
    return 120;
  }
}

class MockMap3D extends HTMLElement {
  mode = "HYBRID";
  private _center: LatLngAlt = { lat: 36.8, lng: -109.5, altitude: 0 };
  private _heading = 0;
  tilt = 45;
  range = 5_000_000;
  roll = 0;
  fov = 35;
  maxTilt = 82;
  defaultUIHidden = true;
  private animTimer: number | null = null;
  private steadyTimer: number | null = null;
  private _steady = false;
  /** Debug log of animations for tests. */
  animations: Array<{ kind: string; durationMillis: number; camera: Record<string, unknown> }> = [];

  connectedCallback(): void {
    this.style.position = "relative";
    this.style.display = "block";
    this.style.overflow = "hidden";
    if (!this.querySelector("canvas")) {
      const canvas = document.createElement("canvas");
      canvas.style.cssText = "position:absolute;inset:0;width:100%;height:100%;background:#0b1520;";
      this.appendChild(canvas);
    }
    this.scheduleSteady();
  }

  /** Place HTML markers from the camera so headless tests can see a Start pin. */
  layoutMarkers(): void {
    const w = this.clientWidth || this.getBoundingClientRect().width;
    const h = this.clientHeight || this.getBoundingClientRect().height;
    if (w < 2 || h < 2) return;
    const lat = this._center.lat;
    const lng = this._center.lng;
    const zoom = zoomFromRange(this.range, lat, h, this.fov || 35);
    const mpp = Math.max(0.01, metersPerPixel(zoom, lat));
    const cos = Math.max(0.2, Math.cos((lat * Math.PI) / 180));
    const heading = ((this._heading || 0) * Math.PI) / 180;
    const sin = Math.sin(heading);
    const c = Math.cos(heading);
    this.querySelectorAll("mmd-mock-marker").forEach((node) => {
      const marker = node as HTMLElement;
      const mlat = Number(marker.dataset.lat);
      const mlng = Number(marker.dataset.lng);
      if (!Number.isFinite(mlat) || !Number.isFinite(mlng)) return;
      const east = (mlng - lng) * 111_320 * cos;
      const north = (mlat - lat) * 111_320;
      const x = (east * c - north * sin) / mpp;
      const y = (-east * sin - north * c) / mpp;
      marker.style.position = "absolute";
      marker.style.display = "block";
      marker.style.width = "max-content";
      marker.style.left = `${w / 2 + x}px`;
      marker.style.top = `${h / 2 + y}px`;
      marker.style.transform = "translate(-50%, -50%)";
      marker.style.zIndex = "6";
    });
  }

  get center(): LatLngAlt {
    return this._center;
  }

  set center(v: LatLngAlt) {
    this._center = { lat: Number(v.lat), lng: Number(v.lng), altitude: Number(v.altitude || 0) };
    this.dispatchEvent(new Event("gmp-centerchange"));
    this.unsteady();
    this.scheduleSteady();
    queueMicrotask(() => this.layoutMarkers());
  }

  /** Like the real element: a camera write leaves the steady state until tiles settle. */
  private unsteady(): void {
    if (!this._steady) return;
    this._steady = false;
    const ev = new Event("gmp-steadychange") as Event & { isSteady: boolean };
    ev.isSteady = false;
    this.dispatchEvent(ev);
  }

  get heading(): number {
    return this._heading;
  }

  set heading(v: number) {
    this._heading = Number(v) || 0;
    this.dispatchEvent(new Event("gmp-headingchange"));
  }

  private scheduleSteady(): void {
    if (this.steadyTimer != null) window.clearTimeout(this.steadyTimer);
    this.steadyTimer = window.setTimeout(() => {
      this.steadyTimer = null;
      this._steady = true;
      const ev = new Event("gmp-steadychange") as Event & { isSteady: boolean };
      ev.isSteady = true;
      this.dispatchEvent(ev);
    }, steadyDelayMs());
  }

  private endAnimation(durationMillis: number, camera: Record<string, unknown>): void {
    this.unsteady();
    if (this.animTimer != null) window.clearTimeout(this.animTimer);
    this.animTimer = window.setTimeout(() => {
      this.animTimer = null;
      const c = camera.center as LatLngAlt | undefined;
      if (c) this.center = c;
      if (camera.heading != null) this.heading = Number(camera.heading);
      if (camera.tilt != null) this.tilt = Number(camera.tilt);
      if (camera.range != null) this.range = Number(camera.range);
      this.dispatchEvent(new Event("gmp-animationend"));
      this.scheduleSteady();
    }, Math.min(durationMillis, 400));
  }

  stopCameraAnimation(): void {
    if (this.animTimer != null) {
      window.clearTimeout(this.animTimer);
      this.animTimer = null;
      this.animations.push({ kind: "stop", durationMillis: 0, camera: {} });
      this.scheduleSteady();
    }
  }

  flyCameraTo(opts: { endCamera: Record<string, unknown>; durationMillis: number }): void {
    this.animations.push({ kind: "flyTo", durationMillis: opts.durationMillis, camera: opts.endCamera });
    this.endAnimation(opts.durationMillis, opts.endCamera);
  }

  flyCameraAround(opts: { camera: Record<string, unknown>; durationMillis: number; rounds?: number }): void {
    this.animations.push({ kind: "flyAround", durationMillis: opts.durationMillis, camera: opts.camera });
    this.endAnimation(opts.durationMillis, opts.camera);
  }
}

class MockPolyline3D extends HTMLElement {
  path: LatLngAlt[] = [];
  strokeColor = "#fff";
  strokeWidth = 1;
  outerColor = "";
  outerWidth = 0;
  altitudeMode = "CLAMP_TO_GROUND";
  drawsOccludedSegments = false;
  zIndex = 0;
  geodesic = false;
}

class MockMarker3D extends HTMLElement {
  position: LatLngAlt = { lat: 0, lng: 0 };
  altitudeMode = "CLAMP_TO_GROUND";
  extruded = false;
  sizePreserved = false;
  zIndex = 0;
}

class MockHtmlMarker extends HTMLElement {
  private _position: LatLngAlt = { lat: 0, lng: 0 };
  altitudeMode = "CLAMP_TO_GROUND";
  anchorLeft = "-50%";
  anchorTop = "-100%";

  get position(): LatLngAlt {
    return this._position;
  }

  set position(v: LatLngAlt) {
    this._position = v;
    this.dataset.lat = String(v.lat);
    this.dataset.lng = String(v.lng);
    const map = this.closest("mmd-mock-map3d") as MockMap3D | null;
    map?.layoutMarkers();
  }
}

class MockModel3D extends HTMLElement {
  src = "";
  position: LatLngAlt = { lat: 0, lng: 0 };
  orientation = { heading: 0, tilt: 0, roll: 0 };
  scale: number | { x: number; y: number; z: number } = 1;
  altitudeMode = "CLAMP_TO_GROUND";
}

type OptionsCtor<T> = new (opts?: Record<string, unknown>) => T;

const registry = new Map<string, OptionsCtor<HTMLElement>>();

/** Register (once) a custom element whose constructor accepts an options bag, like the real API. */
function withOptions<T extends HTMLElement>(tag: string, Base: new () => T): OptionsCtor<T> {
  const existing = registry.get(tag);
  if (existing) return existing as OptionsCtor<T>;
  const Wrapped = class extends (Base as new () => HTMLElement) {
    constructor(opts?: Record<string, unknown>) {
      super();
      if (opts) Object.assign(this, opts);
    }
  };
  define(tag, Wrapped as unknown as CustomElementConstructor);
  registry.set(tag, Wrapped as unknown as OptionsCtor<HTMLElement>);
  return Wrapped as unknown as OptionsCtor<T>;
}

export function createMockMaps3d(): Maps3dLib {
  document.body.classList.add("maps3d-mock");
  return {
    Map3DElement: withOptions("mmd-mock-map3d", MockMap3D) as unknown as Maps3dLib["Map3DElement"],
    Polyline3DElement: withOptions("mmd-mock-polyline3d", MockPolyline3D) as unknown as Maps3dLib["Polyline3DElement"],
    Marker3DElement: withOptions("mmd-mock-marker3d", MockMarker3D) as unknown as Maps3dLib["Marker3DElement"],
    MarkerElement: withOptions("mmd-mock-marker", MockHtmlMarker) as unknown as NonNullable<Maps3dLib["MarkerElement"]>,
    Model3DElement: withOptions("mmd-mock-model3d", MockModel3D) as unknown as NonNullable<Maps3dLib["Model3DElement"]>,
    AltitudeMode: {
      CLAMP_TO_GROUND: "CLAMP_TO_GROUND",
      RELATIVE_TO_GROUND: "RELATIVE_TO_GROUND",
      RELATIVE_TO_MESH: "RELATIVE_TO_MESH",
      ABSOLUTE: "ABSOLUTE",
    },
    MapMode: { HYBRID: "HYBRID", SATELLITE: "SATELLITE" },
  };
}
